pub fn parse_process_line(line: &str) -> Option<ProcessRow> {
    // ...parsing code...
    let mut agent_state = None;
    let mut idle = None;
    for seg in segments {
        let seg = seg.trim();
        if let Some(v) = seg.strip_prefix("state:") {
            agent_state = Some(v.trim().to_string());
        } else if let Some(v) = seg.strip_prefix("idle:") {
            idle = Some(v.trim().to_string());  // age string
        }
        // ...other segments...
