/// Foreground 256-colour SGR code for an agent row, keyed by its live
/// `agent_state` (todo #175). The Agents pane left rows uncoloured; this gives
/// the agent lifecycle the same at-a-glance colour the todo rows carry (#236).
/// `idle` deliberately stands out - it is the "finished, awaiting you" signal
/// the idle bell pairs with - while the active states stay calm. An unknown or
/// absent state paints in the terminal default. Codes track the #236 palette.
pub fn agent_state_fg(state: &str) -> Option<u8> {
    match state {
        "idle" => Some(214),    // amber - needs attention (pairs with the bell)
        "waiting" => Some(160), // red - blocked on input
        "thinking" | "planning" | "working" => Some(34), // green - actively running
        "done" => Some(245),    // gray - finished
        _ => None,              // unknown / unreported -> terminal default
    }
}

